import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const questionsToAppend = {
  technical_docs: [
    {q: "You are a technical writer at a SaaS company. You need to document a webhook system for developers. Explain what webhooks are and what the documentation must cover.", a: `Webhook documentation is frequently inadequate in SaaS products because the writers who produce it understand the concept and forget that many developers have limited webhook experience. Good webhook documentation starts with the right level of assumption about the reader.\n\nWhat webhooks are (for the documentation introduction):\n\nWebhooks allow your application to receive real-time notifications when specific events occur in [Product]. Instead of polling our API repeatedly to check for changes, your server receives an HTTP POST request from us the moment an event happens. This is more efficient for both sides.\n\nFor example: when a customer completes a payment in your application, we send a webhook to your server immediately. Your server can then update your database, send a confirmation email, and trigger any other logic — all automatically.\n\nWhat the documentation must cover:\n\nQuick start: A minimal working example of receiving and processing a webhook — the actual server code to receive the POST request, validate the signature, and return a 200 response. This is the first thing developers want to see.\n\nEvent types: A comprehensive list of all events that trigger webhooks, with the exact event name, a description of when it fires, and the payload schema for each event. This section is navigated, not read.\n\nPayload format: The standard envelope that wraps every webhook payload — the event type, the timestamp, the event ID, and the data object.\n\nSignature verification: How to verify that webhooks are genuinely from the company and not from an attacker. This is a security requirement that many developers implement incorrectly when it is not documented precisely. Include exact code examples.\n\nRetry behavior: How many times the system retries failed webhook deliveries, at what intervals, and what constitutes a failure (non-200 response, timeout). Developers who do not understand retry behavior build systems that process the same event multiple times.\n\nIdempotency: How to handle receiving the same webhook event more than once, which is guaranteed to happen eventually.`, subcategory: null, difficulty: "Hard", domain: "fintech", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a bank. You need to write a disaster recovery plan documentation for the IT team. What are the essential components?", a: `Disaster recovery documentation is tested in the worst possible conditions — during an actual disaster. The documentation must be usable by people under pressure, potentially working from unfamiliar environments, and possibly without access to the systems they normally use. These conditions set the bar for what the documentation must achieve.\n\nEssential components:\n\nRTO and RPO definitions: The document must open by establishing the Recovery Time Objective — how long the business can survive without each system — and the Recovery Point Objective — how much data loss is acceptable. All subsequent procedures are designed to meet these targets.\n\nSystem inventory and criticality classification: A complete list of all systems with their criticality tier. Tier 1 systems must be recovered within the RTO even if Tier 3 systems remain down for extended periods. This classification drives recovery sequence.\n\nCrisis response team: Named individuals and their roles in a disaster event, with backup contacts for each. This must include current contact information — mobile numbers, not just work email — and must be maintained and tested for currency. Nothing fails faster in a real disaster than a contact list with outdated phone numbers.\n\nRecovery procedures by system: Step-by-step procedures for recovering each critical system, written at sufficient detail that someone familiar with the technology but not specifically with this system could execute them. Each procedure should include estimated time to complete.\n\nCommunication procedures: Who is notified when a disaster is declared, in what sequence, and through what channels. For a bank, this includes regulatory notification requirements — RBI requires notification within specified timeframes for major system outages.\n\nTesting and maintenance schedule: How often the DR plan is tested, what types of tests are conducted (tabletop exercises, partial failover tests, full DR tests), and who is responsible for keeping the documentation current.\n\nOffsite storage of the documentation: The DR plan must be accessible when the primary systems are unavailable. A plan stored only on the internal wiki is inaccessible when the internal wiki is part of the disaster.`, subcategory: null, difficulty: "Hard", domain: "banking", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at an insurance company. You need to write end-user documentation for a new claims portal designed for senior users aged 60 and above. What adaptations do you make?", a: `Documentation for senior users requires specific adaptations that go beyond simply using plain language. Research on older adult digital users consistently shows that the most significant barriers are not language complexity but visual design, cognitive load, and assumed familiarity with digital interaction patterns.\n\nFor the documentation specifically:\n\nFont size and visual presentation: I specify a minimum font size of 14 points for printed documentation and recommend 16 points. If the documentation is digital, I advocate for a high-contrast design with generous whitespace. Dense, small text creates barriers even for users with undiagnosed vision changes that come with aging.\n\nOne task per page or section: Senior users are more likely to follow documentation linearly rather than skipping around. I organize the guide so that each page or section contains exactly one task. Combining multiple tasks in one section creates confusion about where one task ends and the next begins.\n\nStep-by-step with explicit screen description: I describe what the user will see at each step, not just what to do. "The screen will show a blue button labeled Submit Claims — click this button" is more useful for a senior user than "Click Submit" because it confirms they are looking at the right element before they act.\n\nScreenshots at every step: Screenshots are particularly important for senior users who may not have strong visual memory of an interface they use infrequently. The screenshots should show the entire screen context, not just the element the user needs to interact with.\n\nGlossary of digital terms: Terms like "browser," "tab," "scroll," "dropdown," and "toggle" should be defined in a glossary. These terms are second nature to regular digital users but are genuinely confusing to users with limited digital experience.\n\nLarge-print and printable version: Many senior users prefer printed documentation. I provide a formatted print-ready version alongside any digital documentation.`, subcategory: null, difficulty: "Medium", domain: "insurance", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a telecom company. Explain the difference between a user manual, a quick start guide, and a reference guide. When would you produce each?", a: `User manuals, quick start guides, and reference guides serve different information needs at different stages of a user's relationship with a product. Understanding the distinction prevents the common mistake of producing one comprehensive document that serves all purposes poorly.\n\nUser manual:\n\nA user manual is a comprehensive guide to everything a product can do, designed for users who want to understand the full capability of the product. It covers every feature in detail, including advanced functionality, edge cases, and settings. User manuals are typically used when a product is complex enough that users cannot discover all its functionality through exploration, or in regulated contexts where the manual serves as a compliance document demonstrating what users were told about the product.\n\nFor a telecom product like a router or a business telephony system, the user manual is the authoritative reference for all functionality.\n\nQuick start guide:\n\nA quick start guide covers the minimum a user needs to get the product working. Its purpose is to get the user from unboxing to first successful use as fast as possible. For a telecom product like a new SIM card or a mobile device, the quick start guide covers activation, basic configuration, and the most important first steps. Everything else is left to the user manual or help center.\n\nQuick start guides are typically two to eight pages, heavily illustrated, and use minimal text. They are designed to be followed, not read.\n\nReference guide:\n\nA reference guide is not designed to be read sequentially — it is designed to be searched. It is the documentation users return to when they have a specific question: what does this setting do, what is this error code, what are the valid values for this parameter. Reference guides assume the user already knows how to use the product generally and needs specific information.\n\nFor telecom technical documentation, reference guides cover things like all available configuration parameters for a network device, all error codes in a billing system, or all API endpoints in a developer portal.`, subcategory: null, difficulty: "Easy", domain: "telecom", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a SaaS company. Your product team asks you to create an in-app tutorial for a complex feature. What is your approach and what are the constraints of in-app tutorials?", a: `In-app tutorials are a powerful onboarding tool when they are designed around what the user wants to do, and a significant source of frustration when they are designed around what the product team wants to show.\n\nApproach:\n\nBefore designing the tutorial, I work with the product team to define the objective: what should the user be able to do after completing the tutorial? This single question eliminates the common trap of tutorial scope creep where every feature gets its own tutorial step regardless of relevance to the user's goal.\n\nI then design the tutorial as a task, not a tour. A tour says "here is the menu, here is the dashboard, here is the settings panel." A task-based tutorial says "let's set up your first report" and only introduces the elements of the product that are needed to complete that specific task. The user learns through doing rather than through observation.\n\nFor a complex feature, I typically design the tutorial in two parts: a minimal path that gets users to a basic working version of the feature, and an optional advanced path for users who want to explore deeper functionality.\n\nConstraints of in-app tutorials:\n\nSkip rate: Most users skip in-app tutorials. The tutorial must provide immediate value or it will be dismissed. Tutorials that cover too many steps before the user gets to do anything real are skipped at very high rates.\n\nState dependency: In-app tutorials often fail when the user's state does not match what the tutorial expects. A tutorial that assumes an empty project fails for a user who already has projects. I design tutorials to be state-aware or to work from a tutorial-specific sandbox environment.\n\nDiscoverability after dismissal: Users who dismiss a tutorial and later need it cannot find it if there is no "replay tutorial" option. I always advocate for an accessible way to restart the tutorial from the help menu.`, subcategory: null, difficulty: "Medium", domain: "fintech", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a bank. A new regulation requires the bank to update disclosures in all customer-facing documentation within 60 days. How do you manage this project?", a: `A 60-day regulatory documentation update project across all customer-facing materials is a content operations emergency that requires immediate triage, centralized coordination, and a clear publication process.\n\nDay 1-3 — Scope and triage:\n\nI conduct a rapid inventory of all customer-facing documentation: website pages, app copy, printed brochures, PDF guides, email templates, SMS templates, and in-branch materials. For each piece, I assess: does this piece contain content affected by the new regulation? If yes, what specifically needs to change? I document this in a master tracking sheet that will be the project's single source of truth.\n\nI also meet with the legal and compliance team to get the exact regulatory language requirements, any flexibility in how the disclosure can be worded, and confirmation of what the regulatory deadline actually requires (some regulations have phased requirements).\n\nDay 4-14 — Content revision:\n\nI prioritize the highest-reach materials first: app copy and website pages that are seen by all customers, then email templates, then PDFs. I write the updated content and submit it for legal review. In a regulatory project, legal review is non-negotiable and the review timeline must be factored into the schedule.\n\nDay 15-30 — Review and approval:\n\nParallel review tracks for legal accuracy and editorial quality. I establish a daily check-in with legal to maintain momentum through the review process, which is often the bottleneck in regulatory documentation projects.\n\nDay 31-50 — Publication:\n\nI coordinate publication across all channels: website updates, app updates through the development team, printer coordination for physical materials, email template updates.\n\nDay 51-60 — Verification and documentation:\n\nI verify that all required updates are live across all channels and document the completion for the regulatory record. In a regulated industry, the compliance record of what was updated and when is as important as the updates themselves.`, subcategory: null, difficulty: "Hard", domain: "banking", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at an insurance company. How do you document an API that processes sensitive health data? What additional considerations apply compared to a standard API?", a: `An API that processes sensitive health data requires documentation that addresses the standard API developer needs while also providing the additional compliance, security, and data handling information that is essential for this category of data.\n\nAdditional considerations compared to a standard API:\n\nData classification and regulatory context: The documentation must clearly state what health data categories the API processes, what regulatory framework governs this data (DPDP Act in India, HIPAA equivalent requirements if the API serves US markets), and what this means for developers who integrate with the API. A developer building on this API needs to understand their own compliance obligations before they start.\n\nData minimization requirements: Health data APIs should document explicitly what data is required versus optional, and what the API does with optional data that is provided. Developers in regulated contexts have obligations around data minimization — they should not send more data than necessary.\n\nConsent documentation: If the API processes data that requires user consent, the documentation must explain how consent is signaled to the API and what the API does when consent is absent or revoked.\n\nData retention and deletion: How long does the API store any passed data? Is there a deletion endpoint? What happens to data when an integration is terminated? These questions have regulatory implications that standard API documentation does not need to address.\n\nAudit trail requirements: Health data APIs in regulated contexts typically need to provide evidence of how data was accessed and processed. The documentation should explain what audit data is available and how to access it.\n\nSecurity requirements: Beyond standard API key authentication, health data APIs may require additional security measures — IP allowlisting, mutual TLS, encryption in transit and at rest requirements for developers. These requirements must be documented before a developer can begin integration planning.\n\nEnvironment separation: Testing with synthetic health data requirements must be documented explicitly. The documentation should include guidance on generating appropriate synthetic test data.`, subcategory: null, difficulty: "Hard", domain: "insurance", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a telecom company. You need to write a change management communication plan for a major system upgrade that will affect 500 internal users. What does this include?", a: `A change management communication plan for a major internal system upgrade is a document that specifies how information about the change will be delivered to affected users before, during, and after the upgrade.\n\nThe plan covers five dimensions:\n\nAudience analysis: The 500 internal users are not a homogeneous group. I identify sub-groups with different relationships to the system: heavy users who use it daily and whose workflows will be significantly disrupted, light users who use it occasionally, technical users who may need more detailed information, and managers who need to understand the business impact. Each group needs communication tailored to their specific concerns and informaiton needs.\n\nMessage architecture: The core messages that must be consistent across all communications: what is changing and why, when the change happens, what users need to do to prepare, where to get help, and how to provide feedback. These messages form the backbone of all communications in the plan.\n\nCommunication timeline:\n\n8 weeks before: Executive announcement of the upcoming change with business rationale.\n6 weeks before: Department-level briefings with more detail about what changes in each team's workflow.\n4 weeks before: Training materials and sessions available to all users.\n2 weeks before: Reminder communications with key dates and preparation checklist.\n1 week before: Final reminder with help resources prominently featured.\nDay of upgrade: Status updates through the day.\nDay after: Confirmation that systems are live and feedback invitation.\n2 weeks after: Survey to assess adoption and identify remaining support needs.\n\nFeedback channels: How users can ask questions and raise concerns. A dedicated email alias, a FAQ document that is updated as questions arise, and regular office hours with the project team.\n\nSuccess metrics: What the communication plan is trying to achieve, measured as: awareness of the change (surveyed before launch), preparation completion rate, help desk contact volume post-launch (lower than baseline indicates effective preparation), and user satisfaction with the communication at 2 weeks post-launch.`, subcategory: null, difficulty: "Medium", domain: "telecom", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a fintech company. What is DITA and how would you use it in a large-scale documentation project?", a: `DITA, which stands for Darwin Information Typing Architecture, is an XML-based open standard for structuring technical documentation. It was developed by IBM and is now maintained by OASIS. It is primarily used in large organizations that produce documentation at scale across multiple products, teams, and output channels.\n\nThe core concept of DITA is topic-based authoring. Instead of writing documentation as continuous documents — chapters, sections, paragraphs — DITA breaks content into discrete, self-contained topics. Each topic covers one concept, one task, or one piece of reference information. Topics are reusable: the same topic about how to authenticate with an API can be included in a quick start guide, a developer guide, and an SDK reference without being copied or maintained in multiple places.\n\nDITA topic types:\n\nConcept topics explain what something is. Task topics describe how to do something, always in numbered steps. Reference topics provide factual information that users look up rather than read — parameter tables, error codes, configuration settings.\n\nHow I would use it in a large-scale fintech documentation project:\n\nFor a fintech company with multiple products sharing common infrastructure — authentication, payment processing, webhooks — DITA enables the authentication documentation to be written once and included in the documentation for every product. When the authentication system changes, updating one DITA topic updates all the documentation that includes it.\n\nFor publishing, DITA content is processed through a DITA Open Toolkit to generate multiple output formats: HTML for the online help center, PDF for downloadable guides, and increasingly, structured data formats that can feed AI knowledge bases.\n\nDITA has a significant learning curve and requires tooling investment — authoring tools like Oxygen XML Editor, and content management systems that support DITA. For a fintech company with a small documentation team producing limited documentation, the overhead is not justified. For a team managing thousands of topics across dozens of products, DITA becomes a productivity and quality multiplier.`, subcategory: null, difficulty: "Hard", domain: "fintech", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a bank. You need to create training documentation for a new core banking system. What makes banking system training documentation different from standard software documentation?", a: `Banking system training documentation operates under constraints and serves purposes that standard software documentation does not encounter, making it a specialized discipline within technical writing.\n\nRegulatory accountability: Every action a bank employee takes in a core banking system can be subject to regulatory audit. The training documentation must not just explain how to perform tasks but also explain why specific procedures exist — which regulatory requirements they satisfy — so that trained staff understand the compliance context, not just the mechanical steps. A staff member who understands that a specific KYC verification step exists because of RBI account opening guidelines is more likely to follow it correctly than one who follows it as a ritual without understanding its purpose.\n\nError consequences: Errors in a core banking system have financial consequences for customers, the bank, and potentially for the individual employee. Training documentation must address error scenarios explicitly and in detail: what happens if a wrong account number is entered, how to reverse a transaction, when to escalate rather than attempt self-correction. Standard software documentation rarely needs this level of error consequence detail.\n\nRole-based access and documentation: Different staff roles have different system access and different responsibilities. The documentation must be structured by role — teller procedures, branch manager override procedures, back-office reconciliation procedures — so that each staff member is trained only on their specific responsibilities rather than on the entire system.\n\nAudit trail requirements: Training documentation for a core banking system typically includes documentation of completion — a record that specific staff have been trained on specific procedures. The documentation must be designed to support this tracking, whether through formal acknowledgment forms or learning management system integration.\n\nUpdate processes: When banking procedures change due to regulatory updates or product changes, the training documentation must be updated and staff must be retrained. The documentation must include clear version information and a process for communicating updates to trained staff.`, subcategory: null, difficulty: "Medium", domain: "banking", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at an insurance company. You have been asked to document a machine learning model used for claim fraud detection. What are the documentation requirements for an AI/ML model in a regulated industry?", a: `Documenting a machine learning model for fraud detection in insurance is a specialized technical writing challenge that intersects with model governance, regulatory compliance, and explainability requirements. The documentation serves multiple audiences: data scientists, business stakeholders, compliance teams, and potentially regulators.\n\nDocumentation requirements:\n\nModel purpose and scope: A clear statement of what the model does, what it is used for, and what it is not designed to handle. For a fraud detection model, this includes the specific claim types it evaluates, the geographic scope, and any policy types or customer segments it excludes.\n\nTraining data documentation: What data was used to train the model, what time period it covers, where it came from, how it was preprocessed, and what the class distribution was. In fraud detection, class imbalance is significant — genuine claims vastly outnumber fraudulent ones — and how this was addressed in training must be documented.\n\nFeature documentation: A complete list of all input features the model uses, with descriptions of each feature, its data type, and its source. In regulated contexts, certain features may be restricted from use in models that affect individuals — characteristics that could constitute discriminatory criteria under applicable law.\n\nModel performance metrics: The accuracy, precision, recall, and AUC-ROC of the model on the evaluation set, with the specific thresholds used for classification decisions. In fraud detection, the trade-off between false positive rate (legitimate claims incorrectly flagged) and false negative rate (fraudulent claims missed) is a business and ethical decision that must be documented.\n\nExplainability: For regulatory compliance and for claims handlers who must act on model outputs, the documentation should explain what factors most significantly influence the model's fraud score. IRDAI guidelines on fair treatment of policyholders require that claim decisions be explainable.\n\nModel monitoring and retraining schedule: How model performance is monitored in production, what triggers a retraining cycle, and how model drift is detected and addressed.`, subcategory: null, difficulty: "Hard", domain: "insurance", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a telecom company. You need to write a network topology document for the engineering team. What information does it need to contain and how do you gather it?", a: `A network topology document for an engineering team is a reference document that must accurately represent the current state of the network infrastructure and be updatable when that state changes. Its accuracy is more important than its elegance — an inaccurate network diagram creates operational risk.\n\nInformation it needs to contain:\n\nNetwork diagrams: Visual representations of how network components connect, organized by layer (core, distribution, access), by geographic region, and by function (data, voice, management). Multiple diagram types serve different purposes and different audiences within the engineering team.\n\nComponent inventory: A complete list of all network devices with their model, firmware version, physical location, IP address, management access information, and role in the network. This inventory must be searchable and must correspond exactly to the diagrams.\n\nInterconnection details: How each device connects to others — port numbers, cable types, VLAN configurations, routing protocols in use. This level of detail is essential for troubleshooting and for capacity planning.\n\nRedundancy and failover: Which paths and components have redundancy, how failover is triggered, and what the expected behavior is during a failover event.\n\nCapacity information: Current utilization rates for key links and devices, and what the capacity thresholds are that trigger upgrade planning.\n\nHow I gather it:\n\nFor existing infrastructure, I combine documentation from network management tools (which can export current configurations and topology automatically), interviews with network engineers who know the undocumented details, and in some cases physical inspection for physical layer information.\n\nThe most important principle for gathering network documentation: do not trust existing documentation as accurate. I treat existing diagrams as a starting point to be verified, not as the source of truth. Networks change faster than documentation and undocumented changes are the norm.`, subcategory: null, difficulty: "Hard", domain: "telecom", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a fintech company. What is the difference between documentation and a specification, and when do you write each?", a: `Documentation and specifications serve different purposes in the software development lifecycle, and conflating them produces documents that do neither job well.\n\nA specification is a prescriptive document that defines what a system should do — written before or during development to guide how something will be built. Specifications are living documents during the design and development phase, and they are written by the people defining what will be built: product managers, architects, and sometimes developers. The audience is the people building the system. The purpose is to constrain and guide implementation decisions.\n\nA specification answers questions like: what are the requirements for this feature, what inputs does this function accept and what outputs does it produce, what are the performance requirements for this API endpoint. Specifications can be functional (what behavior is required) or technical (how the behavior should be implemented).\n\nDocumentation is a descriptive document that explains what a system does — written after or during development to help users, developers, or operators understand and use the system as it exists. Documentation reflects reality; specification defines an intended reality. The audience for documentation is typically broader and less technical than the specification audience.\n\nWhen to write each:\n\nSpecifications are written before implementation, as input to the development process. A feature specification is written by the product manager before engineers begin building. An API specification is written before the API is implemented, possibly using a specification format like OpenAPI.\n\nDocumentation is written after the implementation is complete enough to document accurately, or in parallel with development for iterative documentation. Documenting a feature before it is built is specification, not documentation — even if it is called documentation.\n\nThe practical confusion: developers sometimes call specifications documentation because both are written documents about software. Technical writers must clarify which is needed and when, because the writing process, the review process, and the maintenance process are fundamentally different.`, subcategory: null, difficulty: "Medium", domain: "fintech", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a bank. A new joiner on your documentation team has produced a first draft that is technically accurate but written in a passive, impersonal voice throughout. How do you give feedback and coach them?", a: `Giving feedback to a new writer requires balancing honest assessment with encouragement and providing specific, actionable guidance rather than general criticism. How feedback is given shapes whether the new writer improves quickly or becomes defensive and demoralized.\n\nI start by identifying what the draft does well and say this first, specifically. If the draft is technically accurate, that is genuinely valuable and non-trivial. "The technical content here is solid — you clearly understood what you were writing about and the information is accurate" is honest positive feedback that establishes credibility before the improvement conversation.\n\nFor the passive voice issue, I do not say "this is written in passive voice which is bad." I explain the principle and show the difference:\n\n"There is a pattern in this draft that I want to help you address. Technical writing is most effective when it is direct and tells the reader exactly what to do or what happens. Here is an example from your draft: 'The form should be submitted by the user after all fields have been completed.' Here is the same information in active voice: 'Submit the form after you complete all fields.' The second version is shorter, clearer, and puts the reader at the center of the instruction. This pattern appears throughout the draft — I have marked the instances in the document."\n\nI then ask the new writer to revise a section themselves rather than revising it for them, and I offer to review the revision and discuss what they changed and why.\n\nFor ongoing coaching, I establish a pattern: write, review together, revise, review again. I give specific positive reinforcement when I see improvement. "This paragraph you revised is much stronger — notice how much clearer the instruction is now." Naming the specific improvement helps the writer internalize what good looks like.`, subcategory: null, difficulty: "Medium", domain: "banking", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at an insurance company. You need to write accessibility guidelines for your documentation team. What are the most important accessibility considerations for technical documentation?", a: `Accessibility in technical documentation means ensuring that content is usable by people with disabilities, including visual impairments, cognitive differences, motor impairments, and hearing impairments. In an insurance context, accessibility is both a legal requirement and an ethical obligation.\n\nMost important accessibility considerations:\n\nAlternative text for images and diagrams: Every image, diagram, chart, and screenshot must have descriptive alternative text that communicates the same information as the visual. For process diagrams, the alt text should describe the process, not just label the image as "process diagram." Screen readers read alt text aloud for visually impaired users who cannot see the images.\n\nHeading structure: Documents must use a logical heading hierarchy — H1, H2, H3 — in sequence, never skipping levels. Screen reader users navigate documents by heading structure. A document without proper heading hierarchy is unnavigable for a screen reader user.\n\nColor and contrast: Information must never be conveyed by color alone because color-blind users cannot distinguish it. "Red text indicates an error" is not accessible; "red text with an error icon and the label Error indicates an error" is. Color contrast ratios must meet WCAG standards — 4.5:1 for normal text, 3:1 for large text.\n\nLink text: Links must be descriptively labeled. "Click here" is inaccessible because a screen reader user navigating by links hears a list of "click here" links with no context. "Download the claim form" is accessible because it describes what the link leads to.\n\nTable accessibility: Data tables must have header rows identified as headers, not just formatted to look like headers. Screen readers use table header information to provide context for each cell.\n\nReadable language: Plain language is an accessibility requirement, not just a quality preference. Users with cognitive disabilities, low literacy, or limited English proficiency benefit from short sentences, common words, and clear structure.`, subcategory: null, difficulty: "Medium", domain: "insurance", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
  ],
  ai_content: [
    {q: "You are an AI content designer at a SaaS company. You need to design the conversational flow for an AI onboarding assistant that helps new users set up their account. What are the principles that guide this design?", a: `An AI onboarding assistant has a specific and high-stakes job: get users to the point where they experience the product's core value as quickly as possible, while gathering the setup information needed for the product to work. The principles that guide this design:\n\nPrinciple 1 — Progress over perfection: The onboarding assistant should get users to a working setup quickly, even if it is not a fully optimized setup. A user who has a basic, functional account on day one is more likely to return than one who abandoned a comprehensive setup flow on day one. Required fields only in the initial onboarding; optional customization later.\n\nPrinciple 2 — Explain the why, not just the what: When the assistant asks for information, it should explain why it needs it. "What industry are you in?" feels interrogative. "What industry are you in? We'll tailor the templates and examples to your context." feels useful.\n\nPrinciple 3 — Acknowledge and confirm before proceeding: After each user input, the assistant confirms receipt and meaning before proceeding. "Got it — you're setting up for a team of 12 in financial services. Here's what I'll set up for you:" This prevents the user from feeling like they are filling out a form that disappears into a void.\n\nPrinciple 4 — Make skipping easy but not necessary: Users should be able to skip any step they do not want to complete during onboarding, with the understanding that they can return to it later. But the skip path should not be the most prominent option — the completion path should be.\n\nPrinciple 5 — Celebrate the end: When setup is complete, the assistant should celebrate it specifically. Not "Setup complete" but "You're all set — your workspace is configured for your team. Here's what we set up: [specific list]. Ready to see your first dashboard?"\n\nPrinciple 6 — One question at a time: Conversational onboarding fails when it presents multiple questions simultaneously. Each turn should contain one question. The user's answer determines the next question.`, subcategory: null, difficulty: "Medium", domain: "fintech", tracks: ["AI Content"], companies: [], roundType: "ai_content", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are an AI content engineer at a bank. The bank wants to use AI to generate first drafts of customer complaint responses. What are the risks and how do you mitigate them?", a: `AI-generated complaint responses in a banking context carry significant risks that require careful mitigation, because complaint responses have legal, regulatory, and customer relationship implications that make errors costly.\n\nRisk 1 — Factual inaccuracy about the customer's account:\n\nThe AI may generate a response that references account details, transaction amounts, or policy terms incorrectly. In a complaint context, a factually wrong response from the bank creates a new grievance on top of the original.\n\nMitigation: The AI must have access to the specific customer's verified account data for the complaint in question, and the generated response must be reviewed by a human agent who can verify factual claims before the response is sent.\n\nRisk 2 — Regulatory non-compliance:\n\nRBI grievance redressal guidelines specify what must be included in complaint responses — acknowledgment timelines, resolution procedures, escalation paths, and mandatory disclosure language. An AI that has not been specifically trained on these requirements may generate responses that omit required elements.\n\nMitigation: The system prompt must include the mandatory regulatory elements that all complaint responses must contain, and a compliance check layer should verify their presence before human review.\n\nRisk 3 — Inappropriate tone for sensitive complaints:\n\nComplaints about fraud, unauthorized transactions, or significant financial loss require empathetic, careful communication. An AI that generates a formulaic "thank you for your feedback" response to a customer who has reported losing ₹5 lakhs to fraud creates a serious brand and relationship problem.\n\nMitigation: Complaints must be classified by severity and type before AI response generation. High-severity complaints (fraud, major errors, complaints already escalated to the Banking Ombudsman) should have the AI draft reviewed at senior levels or bypassed entirely.\n\nRisk 4 — Creating legal commitments the bank cannot keep:\n\nAI responses may generate statements that constitute commitments — "we will resolve this within 48 hours," "we will refund the full amount" — that the bank has not authorized.\n\nMitigation: The system prompt must explicitly prohibit commitment language and require qualified language instead. Human review must specifically check for unauthorized commitments.`, subcategory: null, difficulty: "Hard", domain: "banking", tracks: ["AI Content"], companies: [], roundType: "ai_content", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are an AI content designer at an insurance company. Describe what 'grounding' means in the context of AI language models and why it matters for insurance applications.", a: `Grounding, in the context of AI language models, refers to the practice of anchoring the model's responses to specific, verified factual sources rather than allowing it to generate responses based solely on its training data. A grounded AI response is one that can be traced back to a specific source document; an ungrounded response is one generated from the model's learned patterns without a direct source.\n\nWhy grounding matters specifically for insurance applications:\n\nInsurance products have specific, contractual terms. A motor insurance policy from Company A has different coverage limits, exclusions, and deductibles from Company B. An ungrounded AI that answers questions about insurance coverage from its training data about insurance generally may produce responses that are correct for some policies but wrong for the specific policy the customer holds.\n\nFor a customer asking "Does my policy cover flood damage?" the answer must come from that customer's specific policy document, not from general knowledge about what motor insurance typically covers. Grounding the AI to the customer's actual policy document ensures the answer reflects their specific contract.\n\nFor regulatory compliance, grounded responses provide an audit trail. If a customer makes a financial decision based on an AI response about their coverage and the coverage later turns out to be different, a grounded system can demonstrate exactly what the AI referenced when it gave that response. An ungrounded system cannot.\n\nIn practice, grounding in insurance AI applications typically works through RAG — Retrieval Augmented Generation — where the AI retrieves specific policy documents or sections before generating a response, ensuring the response is based on verified sources.`, subcategory: null, difficulty: "Hard", domain: "insurance", tracks: ["AI Content"], companies: [], roundType: "ai_content", whatInterviewerTests: "", commonMistakes: []},
  ],
  content_strategy: [
    {q: "You are a technical writer at a bank. You need to document the bank's incident response procedure for a cybersecurity breach. What makes this documentation different and what are the special considerations?", a: `Cybersecurity incident response documentation has unique requirements that distinguish it from standard operational procedures, because it is used in adversarial conditions — the incident itself may compromise the systems where the documentation is stored.\n\nSpecial considerations:\n\nOffline accessibility: If the cybersecurity incident involves the bank's network or internal systems, the documentation stored on those systems may be inaccessible during the very incident it is designed to address. Incident response documentation must be available offline: printed copies in secured physical locations, offline storage devices, and access through external channels that do not depend on the compromised network.\n\nNeed-to-know access control: Detailed incident response procedures, escalation contacts, and vulnerability information should not be accessible to all staff. The documentation access control must match the sensitivity of the information contained, while ensuring that the people who need it during an incident can access it quickly.\n\nContainment versus disclosure sequence: The documentation must clearly specify the sequence of containment, forensic preservation, and disclosure actions. Incorrect sequencing — disclosing before containing, or containing before preserving forensic evidence — can both worsen the incident and create legal problems.\n\nRegulatory notification requirements: RBI regulations specify notification timelines for cybersecurity incidents at banks. CERT-In also has specific reporting requirements. The documentation must include the specific notification requirements, the notification timelines, the information that must be included in regulatory notifications, and who is authorized to make those notifications.\n\nCommunication security: During a cybersecurity incident, the bank's normal communication channels may be compromised. The documentation must specify alternative communication channels — encrypted messaging apps, out-of-band phone lines — to use when normal channels cannot be trusted.\n\nPost-incident forensic requirements: What evidence must be preserved, in what format, by whom, and for how long, to support both internal investigation and potential law enforcement involvement.`, subcategory: null, difficulty: "Hard", domain: "banking", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are an AI content engineer at a bank. The bank wants to use generative AI to produce first drafts of product descriptions for new financial products. What governance process do you put in place?", a: `Using generative AI to produce first drafts of financial product descriptions requires a governance process that addresses the specific risks of AI-generated financial content: factual inaccuracy, regulatory non-compliance, and commitments the bank did not intend to make.\n\nGovernance process:\n\nStage 1 — Input governance:\n\nBefore the AI generates any content, I establish what inputs it receives and what it does not. The AI should receive: the product's approved term sheet, the intended audience segment, the mandatory regulatory disclosure requirements, the brand voice guidelines, and examples of approved product descriptions for similar products. The AI should not have discretion about product terms — every term in the generated content must come from the approved term sheet, not be inferred or estimated by the model.\n\nStage 2 — Generation with constraints:\n\nThe system prompt constrains the AI's output explicitly: all financial terms must match the approved term sheet exactly, all rates must be taken from the input data (the AI cannot estimate rates), mandatory regulatory language must appear verbatim as provided, and no commitments beyond what is in the term sheet can be made.\n\nStage 3 — Factual accuracy review:\n\nThe first review is a factual accuracy check against the term sheet, conducted by the product team. Every financial term, rate, fee, and condition in the AI-generated draft is verified against the approved term sheet. Any discrepancy is an error, not a suggestion.\n\nStage 4 — Regulatory compliance review:\n\nThe compliance team reviews for mandatory disclosures, prohibited language, and regulatory accuracy. This review cannot be delegated or abbreviated regardless of the AI's output quality.\n\nStage 5 — Legal review for commitment language:\n\nLegal reviews for inadvertent commitments, guarantee language, and any statements that could create obligations the bank did not intend.\n\nStage 6 — Final approval:\n\nAll three review stages must be completed and approved before any AI-generated content is published.`, subcategory: null, difficulty: "Hard", domain: "banking", tracks: ["AI Content"], companies: [], roundType: "ai_content", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a content strategist at a fintech company. How do you create a taxonomy for a financial services help center and why does taxonomy matter?", a: `Taxonomy is the classification system that determines how content is organized and navigated in a help center. It matters because it directly determines whether users can find the information they need — a help center with excellent content but poor taxonomy is functionally inaccessible.\n\nWhy taxonomy matters specifically for financial services:\n\nFinancial services products have overlapping concepts that can be organized in multiple logical ways. "How to transfer money" could be classified under Accounts, Payments, or Features. "Interest on savings" could be under Accounts, Interest & Fees, or How banking works. Without a deliberate taxonomy, similar content ends up in different categories depending on who created it, and users search for content in the obvious category only to find it was placed in a different one.\n\nApproach to creating the taxonomy:\n\nUser research foundation: I base the taxonomy on how users think about their questions, not on how the bank organizes its products internally. Card sorting exercises with representative users reveal the mental models they use to categorize financial information. This is the most important input — without it, the taxonomy reflects internal thinking rather than user thinking.\n\nTop-level categories: For a fintech help center, effective top-level categories typically follow user tasks or life events: Getting started, Managing my account, Payments and transfers, Cards, Loans and credit, Security and fraud, and Fees and charges. These are oriented around what users want to do rather than product names.\n\nDepth limits: Effective help center taxonomies are typically no deeper than three levels. Category → Subcategory → Article. Deeper hierarchies require users to navigate multiple levels to reach content, increasing friction and abandonment.\n\nMultiple entry points: The same article may be relevant to multiple categories. A well-designed taxonomy either allows articles to appear in multiple places (with canonical URLs to avoid search engine duplication) or uses a robust tagging and search system that surfaces content regardless of where it is placed.`, subcategory: null, difficulty: "Medium", domain: "fintech", tracks: ["Content Strategy"], companies: [], roundType: "content_strategy", whatInterviewerTests: "", commonMistakes: []},
  ]
};

const filePath = path.join(__dirname, 'src/data/technicalWritingQuestions.js');
let fileContent = fs.readFileSync(filePath, 'utf-8');

// Simple approach: Find each array in Technical Writer and append
for (const [roundType, questions] of Object.entries(questionsToAppend)) {
  // Look for the pattern: "roundType": [
  // We need to find the closing ] of that array within Technical Writer

  const pattern = `"${roundType}": [`;
  const startIndex = fileContent.indexOf(pattern, fileContent.indexOf('"Technical Writer"'));

  if (startIndex === -1) {
    console.error(`Could not find "${roundType}" array in Technical Writer`);
    continue;
  }

  const bracketStart = fileContent.indexOf('[', startIndex);
  let bracketCount = 0;
  let bracketEnd = bracketStart;

  // Find matching closing bracket
  for (let i = bracketStart; i < fileContent.length; i++) {
    if (fileContent[i] === '[') bracketCount++;
    if (fileContent[i] === ']') bracketCount--;
    if (bracketCount === 0) {
      bracketEnd = i;
      break;
    }
  }

  // Format and insert questions
  const questionStrings = questions.map(q => JSON.stringify(q, null, 6)).join(',\n    ');
  const beforeClose = fileContent.substring(0, bracketEnd);
  const afterClose = fileContent.substring(bracketEnd);

  // Check if array has content
  const arrayContent = fileContent.substring(bracketStart + 1, bracketEnd).trim();
  const separator = arrayContent.length > 0 ? ',\n    ' : '\n    ';

  fileContent = beforeClose + separator + questionStrings + '\n    ' + afterClose;
  console.log(`Added ${questions.length} ${roundType} questions`);
}

fs.writeFileSync(filePath, fileContent, 'utf-8');
console.log('All questions appended successfully!');
